use std::time::Duration;
use std::thread::sleep;

// bounded retry with backoff — never an infinite loop
fn send_with_retry(mut attempt: u32) -> Result<&'static str, String> {
    loop {
        attempt += 1;
        match try_send() {
            Ok(v) => return Ok(v),
            Err(_) if attempt <= 3 => {
                sleep(Duration::from_millis(100 * 2u64.pow(attempt - 1)));
            }
            Err(e) => return Err(e),
        }
    }
}

fn try_send() -> Result<&'static str, String> { Ok("delivered") }

fn main() {
    println!("{:?}", send_with_retry(0));
}

