exercise.solution:
fn verdict(choice: &str) -> &str {
    match choice {
        c if c.contains("unbounded") => "unbounded risk",
        c if c.contains("max size") => "bounded",
        c if c.contains("forever") => "runaway",
        c if c.contains("cancellation") => "cancellable",
        _ => "review",
    }
}

fn main() {
    for c in [
        "unbounded channel of jobs",
        "queue with max size + backpressure",
        "retry forever, no cap",
        "cancellation token checked between steps",
    ] {
        println!("{}: {}", c, verdict(c));
    }
}
